import pandas as pd
import numpy as np
from collections import Counter
import re
import os
from num2words import num2words

# Ensure submission directory exists
os.makedirs("./submission", exist_ok=True)

# Load data
train = pd.read_csv("./input/en_train.csv")
test = pd.read_csv("./input/en_test_2.csv")
sample_sub = pd.read_csv("./input/en_sample_submission_2.csv")

# Build mapping from 'before' to most frequent 'after' in training set
before_to_after = {}
for before, after in zip(train["before"], train["after"]):
    key = str(before)
    if key not in before_to_after:
        before_to_after[key] = Counter()
    before_to_after[key][after] += 1


# Comprehensive fallback normalizer for unseen tokens
def normalize_with_rules(before_str):
    # Skip empty strings
    if not before_str:
        return ""

    # Handle currency like $3.16 -> "three dollars sixteen cents"
    if before_str.startswith("$"):
        try:
            val = float(before_str[1:])
            dollars = int(val)
            cents = round((val - dollars) * 100)
            parts = []
            if dollars > 0:
                parts.append(
                    num2words(dollars, to="cardinal")
                    + " dollar"
                    + ("s" if dollars != 1 else "")
                )
            if cents > 0:
                parts.append(
                    num2words(cents, to="cardinal")
                    + " cent"
                    + ("s" if cents != 1 else "")
                )
            return " and ".join(parts) if parts else "zero dollars"
        except:
            pass

    # Handle percentages: 12% -> "twelve percent"
    if before_str.endswith("%"):
        try:
            num = float(before_str[:-1])
            return num2words(num, to="cardinal") + " percent"
        except:
            pass

    # Handle time like 12:47 or 08:05
    time_match = re.match(r"^(\d{1,2}):(\d{2})$", before_str)
    if time_match:
        try:
            h, m = int(time_match.group(1)), int(time_match.group(2))
            if 0 <= h <= 23 and 0 <= m <= 59:
                hour_word = num2words(h, to="cardinal")
                if m == 0:
                    return hour_word + " hundred"
                elif m < 10:
                    return hour_word + " oh " + num2words(m, to="cardinal")
                else:
                    return hour_word + " " + num2words(m, to="cardinal")
        except:
            pass

    # Handle fractions like 1/2
    frac_match = re.match(r"^(-?\d+)/(\d+)$", before_str)
    if frac_match:
        try:
            num, den = int(frac_match.group(1)), int(frac_match.group(2))
            num_word = num2words(num, to="cardinal")
            den_word = num2words(den, to="ordinal")
            return f"{num_word} {den_word}"
        except:
            pass

    # Handle ordinals like 1st, 2nd, 3rd, 4th
    ord_match = re.match(r"^(\d+)(st|nd|rd|th)$", before_str)
    if ord_match:
        try:
            n = int(ord_match.group(1))
            return num2words(n, to="ordinal")
        except:
            pass

    # Handle plain integers and decimals
    if re.match(r"^-?\d+(\.\d+)?$", before_str):
        try:
            val = float(before_str)
            # Use cardinal for numbers, but avoid very large ones (fallback to original)
            if abs(val) < 1e12:
                if val == int(val):
                    return num2words(int(val), to="cardinal")
                else:
                    # Handle decimals: 12.34 -> "twelve point three four"
                    int_part, frac_part = str(before_str).split(".")
                    int_word = num2words(int(int_part), to="cardinal")
                    frac_word = " ".join(
                        num2words(int(d), to="cardinal") for d in frac_part
                    )
                    return f"{int_word} point {frac_word}"
        except:
            pass

    # If all fallbacks fail, return original
    return before_str


# Main normalize function: try lookup first, then rule-based
def normalize_token(before):
    before_str = str(before)

    # Direct lookup
    if before_str in before_to_after:
        return before_to_after[before_str].most_common(1)[0][0]

    # Rule-based fallback
    return normalize_with_rules(before_str)


# Generate predictions for test set
test["prediction"] = test["before"].apply(lambda x: normalize_token(x))

# Create the 'id' column by combining sentence_id and token_id
test["id"] = test["sentence_id"].astype(str) + "_" + test["token_id"].astype(str)

# Align with sample submission order using the created id column
submission = test.set_index("id").loc[sample_sub["id"]].reset_index()
submission = submission.rename(columns={"prediction": "after"})[["id", "after"]]

# Save submission
submission.to_csv("./submission/submission.csv", index=False)

# Evaluate on a hold-out sample from training data (stratified by class for stability)
np.random.seed(42)
# Use 1% hold-out, stratified to preserve class distribution
train_sample = train.groupby("class", group_keys=False).apply(
    lambda x: x.sample(frac=0.01, random_state=42)
)

# Evaluate accuracy
correct = 0
total = len(train_sample)
for _, row in train_sample.iterrows():
    before_str = str(row["before"])
    true_after = str(row["after"])

    # Use same logic as submission
    if before_str in before_to_after:
        pred_after = before_to_after[before_str].most_common(1)[0][0]
    else:
        pred_after = normalize_with_rules(before_str)

    if str(pred_after) == true_after:
        correct += 1

val_acc = correct / total
print(f"Validation Accuracy (stratified 1% hold-out): {val_acc:.6f}")
